"""A worker thread that drains a queue.Queue and hands each item to a callback.

Backpressure: at most `max_in_flight` items may be admitted at once, counting
the one currently in the callback. Admission is gated by a semaphore rather
than Queue(maxsize=...) so the shutdown sentinel can always be enqueued even
when the worker is saturated -- a bounded queue would deadlock stop().

Overflow policy decides what a producer does when the window is full:
  "block"       -- wait (default), honouring `timeout`, raising queue.Full
  "drop_newest" -- discard the item being offered
  "drop_oldest" -- evict the stalest queued item to make room

Failure policy:
  * Exception from the callback  -> logged, routed to on_error, worker continues.
  * BaseException                -> recorded, worker exits, backlog released.
  * Failure inside the failure   -> swallowed; nothing may unwind _run silently.
"""

import logging
import queue
import threading
import time

log = logging.getLogger(__name__)

_POLL = 0.1          # how often a blocked producer re-checks worker liveness
OVERFLOW_POLICIES = ("block", "drop_newest", "drop_oldest")


class _Sentinel:
    """Distinct, printable stop marker. Compared by identity, never by value."""

    def __repr__(self):
        return "<SHUTDOWN>"


SHUTDOWN = _Sentinel()


def _safe_repr(obj):
    """repr() that cannot itself take down the error handler."""
    try:
        return repr(obj)
    except Exception:
        return f"<unreprable {type(obj).__name__} at 0x{id(obj):x}>"


class QueueWorker:
    """Consume items from a queue in a background thread, with a bounded window.

    The callback runs on the worker thread, one item at a time. `on_error(item,
    exc)` and `on_drop(item)` -- if given -- run on the caller's or worker's
    thread respectively and may not usefully raise; their exceptions are logged
    and dropped. `stopped` is set when the thread exits for any reason, `error`
    holds the BaseException behind an abnormal exit (None on clean shutdown).
    """

    def __init__(self, callback, q=None, name="queue-worker", daemon=True,
                 sentinel=SHUTDOWN, on_error=None, max_in_flight=64,
                 overflow="block", on_drop=None):
        if max_in_flight < 1:
            raise ValueError("max_in_flight must be >= 1")
        if overflow not in OVERFLOW_POLICIES:
            raise ValueError(f"overflow must be one of {OVERFLOW_POLICIES}")
        self.callback = callback
        self.on_error = on_error
        self.on_drop = on_drop
        self.queue = q if q is not None else queue.Queue()
        self.sentinel = sentinel
        self.max_in_flight = max_in_flight
        self.overflow = overflow
        self.error = None
        self.failures = 0
        self.dropped = 0
        self.stopped = threading.Event()
        # One permit per admitted item; released once the item leaves the system.
        self._slots = threading.BoundedSemaphore(max_in_flight)
        self._thread = threading.Thread(target=self._run, name=name, daemon=daemon)
        self._started = False
        self._stopping = False
        self._lock = threading.Lock()

    # ---------------------------------------------------------------- lifecycle

    def start(self):
        if self._started:
            raise RuntimeError("worker already started")
        self._started = True
        self._thread.start()
        return self

    def stop(self, timeout=None, wait=True):
        """Enqueue the sentinel, then optionally join the thread. Idempotent.

        The sentinel bypasses the admission window, so this never blocks on a
        full worker -- but it still queues *behind* the backlog, so pending
        items are processed first.
        """
        with self._lock:
            if not self._started:
                return
            already, self._stopping = self._stopping, True
        if not already and not self.stopped.is_set():
            self.queue.put(self.sentinel)
        if wait:
            self._thread.join(timeout)

    @property
    def alive(self):
        return self._started and self._thread.is_alive()

    @property
    def in_flight(self):
        """Items admitted but not yet finished (queued + the one being run)."""
        return self.max_in_flight - self._slots._value

    def __enter__(self):
        return self.start()

    def __exit__(self, *exc):
        self.stop()
        return False

    # ---------------------------------------------------------------- admission

    def _acquire_slot(self, block, timeout):
        """Take one admission permit. Polls so a dead worker can't hang a producer."""
        if not block:
            return self._slots.acquire(False)
        deadline = None if timeout is None else time.monotonic() + timeout
        while True:
            if self.stopped.is_set():
                raise RuntimeError("worker is not running") from self.error
            wait = _POLL if deadline is None else min(_POLL, deadline - time.monotonic())
            if wait <= 0:
                return False
            if self._slots.acquire(True, wait):
                return True

    def _release_slot(self):
        try:
            self._slots.release()
        except ValueError:      # over-release after a racing drain; harmless
            pass

    def _note_drop(self, item):
        self.dropped += 1
        try:
            log.warning("dropped item %s (in-flight limit %d reached)",
                        _safe_repr(item), self.max_in_flight)
        except Exception:
            pass
        if self.on_drop is None:
            return
        try:
            self.on_drop(item)
        except Exception:
            try:
                log.exception("on_drop handler itself failed")
            except Exception:
                pass

    def put(self, item, block=True, timeout=None):
        """Submit an item. Returns True if admitted, False if dropped.

        Raises queue.Full under the "block" policy when `timeout` expires, and
        RuntimeError if the worker has already exited.
        """
        if item is self.sentinel:
            raise ValueError("use stop() to retire the worker")
        if self.stopped.is_set():
            raise RuntimeError("worker is not running") from self.error

        if self._acquire_slot(block and self.overflow == "block", timeout):
            self.queue.put(item)
            return True

        if self.overflow == "block":
            raise queue.Full(f"{self.max_in_flight} items already in flight")
        if self.overflow == "drop_newest":
            self._note_drop(item)
            return False

        # drop_oldest: evict one queued item, reusing its permit for the new one.
        for _ in range(3):
            try:
                stale = self.queue.get_nowait()
            except queue.Empty:
                if self._acquire_slot(False, None):   # worker just freed a slot
                    self.queue.put(item)
                    return True
                continue
            if stale is self.sentinel:                # never evict the stop signal
                self.queue.put(stale)
                break
            self.queue.task_done()
            self._note_drop(stale)
            self.queue.put(item)
            return True
        self._note_drop(item)
        return False

    # ------------------------------------------------------------------- worker

    def _handle_failure(self, item, exc):
        """Report a failed item. Must never raise -- it runs inside _run's try."""
        self.failures += 1
        try:
            log.error("callback failed for item %s", _safe_repr(item), exc_info=exc)
        except Exception:   # a broken logging handler is not worth dying over
            pass
        if self.on_error is None:
            return
        try:
            self.on_error(item, exc)
        except Exception:
            try:
                log.exception("on_error handler itself failed")
            except Exception:
                pass

    def _run(self):
        try:
            while True:
                item = self.queue.get()
                is_sentinel = item is self.sentinel
                try:
                    if is_sentinel:
                        return
                    self.callback(item)
                except Exception as exc:
                    self._handle_failure(item, exc)
                except BaseException as exc:
                    # KeyboardInterrupt, SystemExit, MemoryError, GeneratorExit:
                    # not recoverable per-item, so exit -- but leave a trace.
                    self.error = exc
                    self._handle_failure(item, exc)
                    return
                finally:
                    self.queue.task_done()
                    if not is_sentinel:      # the sentinel never took a permit
                        self._release_slot()
        except BaseException as exc:
            # Raised by queue.get()/task_done() itself -- outside the inner guard.
            self.error = exc
            try:
                log.critical("worker loop died", exc_info=exc)
            except Exception:
                pass
        finally:
            self.stopped.set()               # set first: unblocks producers
            self._release_backlog()

    def _release_backlog(self):
        """Unblock join_queue() and any waiting producers once we're done."""
        while True:
            try:
                item = self.queue.get_nowait()
            except queue.Empty:
                break
            except Exception:
                break
            try:
                self.queue.task_done()
            except Exception:
                break
            if item is not self.sentinel:
                self._release_slot()
        for _ in range(self.max_in_flight):  # free anyone mid-acquire
            self._release_slot()

    def join_queue(self, timeout=None):
        """Block until submitted items are processed (or the worker has died)."""
        self.queue.join()
        if self.error is not None:
            raise RuntimeError("worker died") from self.error


def stop_all(workers, timeout=None):
    """Retire a fan-out pool sharing one queue: one sentinel per consumer."""
    for w in workers:
        w.stop(wait=False)
    for w in workers:
        w.stop(timeout=timeout)


if __name__ == "__main__":
    logging.basicConfig(level=logging.INFO)

    def slow(n):
        time.sleep(0.05)
        if n == 2:
            raise ValueError("two is unlucky")
        print(f"got {n} -> {n * n}")

    # Bounded window, newest-wins: the producer never blocks behind a slow callback.
    with QueueWorker(slow, max_in_flight=3, overflow="drop_oldest",
                     on_error=lambda i, e: print(f"failed {i}: {e}")) as w:
        for i in range(50):
            w.put(i)                      # returns immediately, sheds stale work
        w.join_queue()
        print(f"failures={w.failures} dropped={w.dropped}")
```

The window is a `BoundedSemaphore`, not `Queue(maxsize=...)`, for one specific reason: with a bounded queue, `stop()` would have to block to insert the sentinel, so a saturated worker plus a producer that has gone away is an unbreakable deadlock. Here the sentinel bypasses admission entirely and still lands behind the backlog, so shutdown stays both non-blocking and ordered.

`_acquire_slot` polls in 100 ms steps rather than blocking outright, so a producer waiting on a window that will never reopen — the worker died mid-item — gets a `RuntimeError` chained off `self.error` instead of hanging until the process ends. That's also why `_run`'s `finally` sets `stopped` *before* draining: the flag is what the waiters are checking.

`drop_oldest` evicts a queued item and reuses its permit for the incoming one, so it performs no net release — the permit accounting stays one-per-live-item. It refuses to evict the sentinel, which would otherwise turn a shutdown into a silent hang. With `overflow="block"` (the default) and no timeout, behaviour is the familiar one: producers throttle to the callback's actual rate.
